/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {*} newstkIsuTpContn newstkIsuTpContn
 * @param {*} isuKorAbbrv isuKorAbbrv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (newstkIsuTpContn, isuKorAbbrv) {
    let str = "";
    str += "newstkIsuTpContn : " + newstkIsuTpContn + "\n";
    str += "isuKorAbbrv : " + isuKorAbbrv + "\n";
    const returnKey = '' + dma_pageContext.get("returnKey") + '';
    try {
